      const rate = await this.api.set(sheet.id, grade, pct.trim(), from.trim() === '' ? null : from.trim());
      if (this.session.sheet()?.id === sheet.id) this.saved.emit(rate);
    } catch {
      this.error.set('The rate could not be set.');
    } finally {
      this.saving.set(false);
    }
  }
